import {clsx} from 'clsx'

import {type RefObject, useState} from 'react'
import {Button, Heading} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'
import {GearIcon} from '@primer/octicons-react'
import {BetaLabel} from '@github-ui/lifecycle-labels/beta'

import {useUpdateAlertAssigneesMutation} from '../hooks/use-update-alert-assignees-mutation'
import type {Assignee} from '../types'
import {AssigneePicker} from './AssigneePicker'
import {AssigneesList} from './AssigneesList'

import styles from './AssigneesSection.module.css'

export type AssigneesSectionProps = {
  className?: string
  availableAssigneesPath: string
  updateAssigneesPath: string
  currentUser: Assignee
  assignees: Assignee[]
  readonly: boolean
  maxAssignees?: number
  onAssignmentChange?: () => void
  copilotAssignableAlert?: boolean
  showBetaLabel?: boolean
}

export function AssigneesSection({
  className,
  availableAssigneesPath,
  updateAssigneesPath,
  currentUser,
  assignees: initialAssignees,
  readonly,
  maxAssignees = 10,
  onAssignmentChange,
  copilotAssignableAlert = false,
  showBetaLabel = true,
}: AssigneesSectionProps) {
  const [assignees, setAssignees] = useState<Assignee[]>(initialAssignees)
  const [showCopilotAssignmentMessage, setShowCopilotAssignmentMessage] = useState(false)
  const {
    mutate: mutateUpdateAssignees,
    isPending: mutationPending,
    error: mutationError,
  } = useUpdateAlertAssigneesMutation(updateAssigneesPath)

  return (
    <div className={clsx('d-flex flex-column flex-items-start position-relative width-full', className)}>
      {showCopilotAssignmentMessage && (
        <InlineMessage variant="success" size="small" className="pb-2">
          Successfully assigned to Copilot to apply the autofix for this alert. Copilot will open a PR.
        </InlineMessage>
      )}
      <div className="width-full">
        {readonly ? (
          <div className="width-full position-relative pb-2">
            <div className="d-flex flex-items-center gap-2">
              <Heading as="h3" className={clsx('top-1 f6 color-fg-muted', styles.sectionHeading)}>
                Assignees
              </Heading>
              {showBetaLabel && <BetaLabel />}
            </div>
          </div>
        ) : (
          <AssigneePicker
            path={availableAssigneesPath}
            copilotAssignableAlert={copilotAssignableAlert}
            anchorElement={(props: React.HTMLAttributes<HTMLElement>, ref: RefObject<HTMLButtonElement | null>) => (
              <div className="width-full position-relative">
                <div
                  className="top-1 mt-1 position-absolute d-flex flex-items-center gap-2"
                  style={{pointerEvents: 'none'}}
                >
                  <Heading as="h3" className={clsx('f6 color-fg-muted', styles.sectionHeading)}>
                    Assignees
                  </Heading>
                  {showBetaLabel && <BetaLabel />}
                </div>
                <Button
                  ref={ref}
                  {...props}
                  variant="invisible"
                  size="small"
                  trailingAction={GearIcon}
                  block
                  className="flex-content-start pl-0"
                >
                  <span className="sr-only f6 text-bold color-fg-muted lh-default">Edit assignees</span>
                </Button>
              </div>
            )}
            initialSelectedAssignees={assignees}
            currentUser={currentUser}
            maximumAssignees={maxAssignees}
            onSelectionChange={(selectedAssignees: Assignee[]) =>
              mutateUpdateAssignees(
                {assigneeIds: selectedAssignees.map(a => a.id)},
                {
                  onSuccess: data => {
                    setAssignees(data ? data.assignees : selectedAssignees)
                    setShowCopilotAssignmentMessage(data?.isCopilotAssignmentNew ?? false)
                    onAssignmentChange?.()
                  },
                },
              )
            }
            shortcutsEnabled={false}
            title={`Assign up to ${maxAssignees} people to this alert`}
            mutationError={mutationError}
            loading={mutationPending}
          />
        )}

        {assignees.length > 0 ? (
          <div className="width-full p-0">
            <AssigneesList assignees={assignees} />
          </div>
        ) : (
          <>
            <span className="d-flex gap-1 pr-2 mb-2 mt-1 f6 color-fg-muted">
              {readonly ? (
                <>No one assigned</>
              ) : (
                <>
                  No one -{' '}
                  <Button
                    loading={mutationPending}
                    variant="link"
                    onClick={() =>
                      mutateUpdateAssignees(
                        {assigneeIds: [currentUser.id]},
                        {
                          onSuccess: () => {
                            setAssignees([currentUser])
                            onAssignmentChange?.()
                          },
                        },
                      )
                    }
                    className={clsx('color-fgAccent text-normal', styles.assignYourselfButton)}
                  >
                    Assign yourself
                  </Button>
                </>
              )}
            </span>
          </>
        )}
      </div>
    </div>
  )
}

try{ AssigneesSection.displayName ||= 'AssigneesSection' } catch {}